-- V150: Checkride Binder Builder -- authored content seed (Phase 2 of 4).
--
-- Transcribed faithfully from Apex_Checkride_Binder_v09_Digital_Fillable.pdf
-- (80 pages, all 20 master-checklist sections plus front-matter/dashboard
-- and per-Part closeout utility pages -- nothing summarized or dropped,
-- per the explicit full-fidelity decision this feature was built against).
-- Populates checkride_binder_content (schema: supabase-portal-schema-v149).
--
-- Run this in the Supabase SQL editor, after supabase-portal-schema-v149.

-- 27 sections total: the 20 master-checklist items plus 7 front-matter/dashboard/closeout utility pages (master-status, master-checklist, open-items-log, countdown-7day, part1-closeout, part2-closeout, part3-closeout).

insert into public.checkride_binder_content (section_id, content) values ('start-here', '{"title":"Start Here / How to Use","pages":"2-3","intro":"This workbook is designed to help you organize, verify, and explain -- not simply collect paper. Your checkride should not start with a scavenger hunt: the goal is to know what you have, know where it is, and know why it matters.","sourceCheck":"Training aid + organization system. Verify current requirements using authoritative sources.","computed":false,"blocks":[{"type":"note","title":"What This Book Does","text":"Helps you gather, locate, verify, and explain the materials that support your practical-test readiness."},{"type":"note","title":"What It Does Not Do","text":"It does not replace the regulations, ACS, aircraft records, FAA guidance, or your recommending instructor."},{"type":"note","title":"The Source Rule","text":"If a requirement is uncertain, stop and verify it in the current authoritative source before checkride day."},{"type":"note","title":"Important","text":"Requirements can vary with certificate sought, aircraft, training path, medical qualification, and individual circumstances. Use this workbook as a structured preparation aid, then verify applicable requirements with current FAA sources and your recommending instructor."},{"type":"note","title":"How To Use This Workbook","text":"01 Start With The Applicant -- confirm identity, certificate/application information, knowledge-test documentation, endorsements, and training records. 02 Audit The Aircraft -- locate aircraft documents, maintenance records, inspection evidence, AD status, and aircraft-specific reference material. 03 Build The Flight Packet -- organize route, weather, NOTAMs, fuel, weight and balance, performance, and contingency planning. 04 Practice \"Show Me\" -- be able to locate the supporting source quickly and explain how it applies to your actual checkride flight."},{"type":"note","title":"Your Rule","text":"Do not check a box because you think an item is complete. Check it because you verified it. Anything uncertain becomes an open item."},{"type":"note","title":"Final Standard","text":"By the end of the workbook, every open item should be verified, corrected, or reviewed with your instructor -- and you should be able to find the supporting material quickly."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('binder-setup', '{"title":"Binder Setup Map","pages":"4","intro":"A good checkride binder is not measured by how thick it is. It is measured by how quickly you can find what you need and explain what you are showing.","sourceCheck":"10 tabs. Everything you need. Nothing extra.","computed":false,"blocks":[{"type":"note","title":"01 Applicant","text":"Identification checklist, pilot certificate information, medical qualification information, personal documents."},{"type":"note","title":"02 Application / IACRA","text":"Application review, FTN/application information, final administrative checks."},{"type":"note","title":"03 Knowledge Test","text":"Airman Knowledge Test Report and deficiency-review documentation."},{"type":"note","title":"04 Endorsements & Experience","text":"Required endorsements, logbook audit, aeronautical-experience verification."},{"type":"note","title":"05 Aircraft Documents","text":"Registration, airworthiness certificate, operating limitations/POH/AFM information."},{"type":"note","title":"06 Airworthiness & Maintenance","text":"Inspection records, AD review, maintenance-record references, discrepancies."},{"type":"note","title":"07 Cross-Country","text":"Route planning, navigation log, airport information, fuel planning."},{"type":"note","title":"08 Weather","text":"Briefing information, weather products, hazards, go/no-go reasoning."},{"type":"note","title":"09 W&B / Performance","text":"Weight and balance, takeoff/landing performance, aircraft limitations."},{"type":"note","title":"10 References","text":"Supporting material you genuinely expect to use or show."},{"type":"fields","title":"Digital Materials","items":[{"id":"primary-efb","label":"Primary EFB / device"},{"id":"backup-efb","label":"Backup source/device"}]},{"type":"checklist","title":"Digital Materials Checklist","items":[{"id":"offline-access-verified","label":"Offline access verified"}]},{"type":"choice","title":"The 30-Second Test","text":"Pick any item in your binder. Can you locate it within approximately 30 seconds?","id":"thirty-second-test","options":["Yes","Not yet"]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('master-status', '{"title":"Master Status","pages":"5","intro":"See the big picture. Track your progress. Finish strong. This page updates automatically from your progress through the workbook -- the paper version asks you to hand-count; the digital version computes it for you.","sourceCheck":null,"computed":true,"blocks":[{"type":"note","title":"Part Status","text":"Automatically computed from each Part''s closeout checklist: 01 The Applicant (documents, application, knowledge test, endorsements), 02 The Aircraft (documents, inspections, airworthiness, aircraft knowledge), 03 The Flight (cross-country, weather, W&B, performance, ADM), 04 The Oral (show-me drills, source use, answer framework), 05 Final Readiness (instructor review, night-before, checkride morning)."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('master-checklist', '{"title":"Master Checklist","pages":"6","intro":"Use this checklist to track completion of every section in this workbook. Check it only when the section is actually ready.","sourceCheck":null,"computed":true,"blocks":[{"type":"note","title":"20 Sections. One Complete System.","text":"This page mirrors the 20 sections of the workbook and their real completion state, computed from your actual responses rather than hand-entered."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('open-items-log', '{"title":"Open Items Log","pages":"7","intro":"Track anything that still needs to be located, corrected, verified, or reviewed with your instructor. Do not carry an unknown item into checkride day.","sourceCheck":null,"computed":false,"blocks":[{"type":"tracker","title":"Open Items","entryLabel":"Open item","columns":[{"id":"category","label":"Category","type":"select","options":["Locate","Verify","Correct","Review with CFI"]},{"id":"description","label":"I still need to..."},{"id":"owner","label":"Owner"},{"id":"due","label":"Due"},{"id":"resolved","label":"Resolved","type":"checkbox"}]},{"type":"fields","title":"Notes / Next Steps","items":[{"id":"notes","label":"Notes / next steps","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('countdown-7day', '{"title":"7-Day Completion Plan","pages":"8","intro":"Use this plan to finish your binder before checkride day. Adjust the dates to match your schedule.","sourceCheck":null,"computed":false,"blocks":[{"type":"checklist","title":"One Week. One Clear Plan.","items":[{"id":"day7","label":"Day 7 (one week out): Complete applicant documents section; verify IACRA and knowledge test information"},{"id":"day6","label":"Day 6 (six days out): Finish endorsements & experience audit; organize aircraft documents"},{"id":"day5","label":"Day 5 (five days out): Complete maintenance & airworthiness section; review aircraft systems and limitations"},{"id":"day4","label":"Day 4 (four days out): Finish cross-country packet and planning; complete weather, W&B, and performance sections"},{"id":"day3","label":"Day 3 (three days out): Work through DPE \"Show Me\" drill; practice oral answer framework"},{"id":"day2","label":"Day 2 (two days out): Complete final review with instructor; resolve all open items"},{"id":"day1","label":"Day 1 (day before): Use the Night-Before Checklist; get rest and be ready"}]},{"type":"fields","title":"My Goal","items":[{"id":"goal-date","label":"All sections complete and ready for instructor review by"}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('applicant-documents', '{"title":"Applicant Documents","pages":"10-11","intro":"Before auditing the airplane, start with you. Confirm your personal, certificate, medical, knowledge-test, and application documents are complete and ready.","sourceCheck":"Right documents. Right place. Checkride ready.","computed":false,"blocks":[{"type":"checklist","title":"Identity","items":[{"id":"gov-id-ready","label":"Government-issued ID ready"},{"id":"name-matches-iacra","label":"Name matches IACRA"},{"id":"dob-matches","label":"Date of birth matches"},{"id":"no-name-discrepancies","label":"No name discrepancies"}]},{"type":"checklist","title":"FAA / Certificate Documents","items":[{"id":"current-certificate","label":"Current pilot certificate (if any)"},{"id":"medical-ready","label":"Medical qualification ready"},{"id":"logbook-ready","label":"Logbook / training record ready"},{"id":"graduation-cert","label":"Graduation certificate (if applicable)"}]},{"type":"checklist","title":"Knowledge Test / Application","items":[{"id":"aktr-ready","label":"Knowledge Test Report ready"},{"id":"test-within-validity","label":"Test within validity period"},{"id":"iacra-complete","label":"IACRA application complete"},{"id":"ftn-recorded","label":"FTN / Application ID recorded"}]},{"type":"checklist","title":"Instructor Sign-Off","items":[{"id":"endorsements-complete","label":"Required endorsements complete"},{"id":"experience-verified","label":"Aeronautical experience verified"},{"id":"application-reviewed-cfi","label":"Application reviewed by CFI"},{"id":"ready-for-certification","label":"Ready for instructor certification"}]},{"type":"fields","title":"Open Items Before Checkride","items":[{"id":"open-items","label":"Open items before checkride","multiline":true}]},{"type":"note","title":"Identity Consistency Check","text":"Your name, date of birth, and identifying information must match across the documents used for your application. Find and resolve discrepancies before checkride day."},{"type":"grid","title":"Identity Consistency Check","columns":[{"id":"gov-id","label":"Government ID"},{"id":"iacra","label":"IACRA Application"},{"id":"aktr","label":"Knowledge Test Report"},{"id":"certificate","label":"Pilot Certificate"}],"rows":[{"id":"name","label":"Name"},{"id":"dob","label":"Date of Birth"},{"id":"doc-type-or-app-id","label":"Document Type / Application ID / Test ID / Certificate Number"},{"id":"exp-or-ftn","label":"Expiration Date / FTN / Test Date / Certificate Type"}]},{"type":"choice","title":"Does Everything Match?","id":"identity-match","options":["Yes -- all information matches","No -- discrepancy found; resolve before checkride","Not applicable / document not held"]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('iacra-application', '{"title":"IACRA & Application","pages":"12","intro":"Confirm that your application is accurate and complete before your instructor certifies and signs it. Catch administrative errors now -- the goal is a clean handoff to your instructor and examiner.","sourceCheck":null,"computed":false,"blocks":[{"type":"fields","title":"Application Details","items":[{"id":"ftn","label":"FAA Tracking Number (FTN)"},{"id":"iacra-app-id","label":"IACRA Application ID"},{"id":"certificate-sought","label":"Certificate Sought"},{"id":"category","label":"Category"},{"id":"class","label":"Class"},{"id":"aircraft-planned","label":"Aircraft Planned for Practical Test"},{"id":"recommending-instructor","label":"Recommending Instructor"}]},{"type":"checklist","title":"Review Checklist","items":[{"id":"personal-info-correct","label":"Personal information is correct"},{"id":"cert-cat-class-correct","label":"Certificate, category, and class are correct"},{"id":"aktr-id-correct","label":"Knowledge Test ID entered correctly"},{"id":"test-validity-verified","label":"Knowledge test timing / any applicable exception verified"},{"id":"training-completed","label":"All required training completed"},{"id":"endorsements-complete","label":"Required endorsements are complete"},{"id":"application-reviewed-cfi","label":"Application reviewed by CFI"},{"id":"ready-for-signature","label":"Ready for instructor certification/signature"}]},{"type":"choice","title":"Application Status","id":"application-status","options":["Submitted and ready","Draft complete -- instructor review required","Correction required"]},{"type":"fields","title":"Notes / Corrections Needed","items":[{"id":"notes","label":"Notes / corrections needed","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('knowledge-test-report', '{"title":"Knowledge Test Report","pages":"13-14","intro":"Verify your Airman Knowledge Test Report and review every deficient knowledge area with your instructor. Your score is only the start -- the deficiency codes become part of your oral preparation.","sourceCheck":"Standard rule: 24 calendar months. Limited relief may apply under 14 CFR §61.40; verify applicability.","computed":false,"blocks":[{"type":"fields","title":"Test Report Information","items":[{"id":"test-date","label":"Test Date"},{"id":"score","label":"Score"},{"id":"test-id","label":"Test ID"},{"id":"expiration-date","label":"Expiration Date / Standard Valid-Through Date"},{"id":"testing-center","label":"Testing Center"},{"id":"report-location","label":"Report Located In"},{"id":"certificate-rating","label":"Certificate / Rating"},{"id":"instructor-review-date","label":"Instructor Review Date"}]},{"type":"choice","title":"Test Status","id":"test-status","options":["Standard 24-month validity period verified","Within applicable exception period","Ready for practical test"]},{"type":"tracker","title":"Deficient Knowledge Areas","entryLabel":"Deficient area","columns":[{"id":"code-subject","label":"Code / Subject Area"},{"id":"how-addressed","label":"How I Addressed It"},{"id":"cfi","label":"CFI"}]},{"type":"checklist","title":"Instructor Review","items":[{"id":"deficient-areas-reviewed","label":"Deficient areas reviewed with instructor"},{"id":"ready-for-practical","label":"Ready for practical test"}]},{"type":"fields","title":"Instructor Sign-Off","items":[{"id":"cfi-initials","label":"CFI initials"},{"id":"date","label":"Date"}]},{"type":"tracker","title":"Knowledge Deficiency Review","entryLabel":"Deficiency review","columns":[{"id":"area-code","label":"Knowledge area / code"},{"id":"misunderstood","label":"What I misunderstood"},{"id":"source","label":"Source I used to verify it"},{"id":"can-explain","label":"I can explain this without reading from a note","type":"checkbox"}]},{"type":"checklist","title":"Ready To Close This Section?","items":[{"id":"every-deficiency-reviewed","label":"Every deficiency has been reviewed"},{"id":"can-show-source","label":"I can show the supporting source"},{"id":"cfi-reviewed","label":"CFI reviewed"}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('endorsements-experience', '{"title":"Endorsements & Experience","pages":"15-21","intro":"Do not memorize a generic list and assume it fits your training path. Identify the endorsements actually required for your certificate, aircraft, and practical-test situation, then verify your logged aeronautical experience against the actual logbook entries.","sourceCheck":"14 CFR §§ 61.39, 61.103, 61.109; FAA AC 61-65K (active 2025-11-14).","computed":false,"blocks":[{"type":"choice","title":"My Training / Test Path","id":"training-path","options":["Part 61","Part 141","Other / special circumstance"]},{"type":"fields","title":"Training Path Details","items":[{"id":"aircraft-category-class","label":"Aircraft category / class"},{"id":"instructor-reviewed","label":"Instructor reviewed"}]},{"type":"dual_checklist","title":"Endorsement Map","subLabels":["Found","Verified"],"items":[{"id":"practical-test-prereq","label":"Practical-Test Prerequisite -- recent practical-test preparation + instructor certification that you are prepared"},{"id":"knowledge-deficiency-review-endt","label":"Knowledge Deficiency Review -- instructor certification that deficient knowledge-test areas were reviewed satisfactorily"},{"id":"private-pilot-practical-test","label":"Private Pilot Practical Test -- training/proficiency endorsement for the certificate/rating sought"},{"id":"student-solo-history","label":"Student / Solo History -- pre-solo, solo, cross-country, make/model, or other endorsements that remain relevant to your record"},{"id":"training-path-specific","label":"Training-Path Specific -- Part 141 graduation documentation or other approvals/endorsements that apply to your path"}]},{"type":"note","title":"Do Not Copy Sample Wording Blindly","text":"Use AC 61-65K as the current FAA endorsement guidance, then have your recommending instructor verify the exact endorsements and wording that apply to you."},{"type":"tracker","title":"Endorsement Tracker","entryLabel":"Endorsement","columns":[{"id":"purpose","label":"Endorsement / purpose"},{"id":"location","label":"Logbook / record location"},{"id":"date","label":"Date"},{"id":"instructor","label":"Instructor"},{"id":"certificate-info","label":"Certificate / RE info"},{"id":"notes","label":"Notes / applicability"},{"id":"located","label":"Entry located / Located","type":"checkbox"},{"id":"legible-complete","label":"Legible / complete","type":"checkbox"},{"id":"verified","label":"Verified by recommending instructor / No correction needed","type":"checkbox"}]},{"type":"tracker","title":"Missing-Item Action Plan","entryLabel":"Missing item","columns":[{"id":"item","label":"Item"},{"id":"action","label":"Action"},{"id":"owner","label":"Owner"},{"id":"due","label":"Due"}]},{"type":"checklist","title":"Endorsement Audit Sign-Off","items":[{"id":"every-endorsement-identified","label":"Every required endorsement for my actual path has been identified"},{"id":"instructor-reviewed-section","label":"My recommending instructor has reviewed this section"}]},{"type":"choice","title":"Aeronautical Experience Dashboard: Path","id":"experience-path","options":["This is my path (Private Pilot -- Airplane Single-Engine -- Part 61)","Different path -- use my approved course / instructor requirements instead"]},{"type":"grid","title":"Aeronautical Experience Dashboard (Part 61 ASEL minimums)","columns":[{"id":"minimum","label":"Part 61 Minimum (reference only)"},{"id":"logged","label":"Logged"},{"id":"cfi-verified","label":"CFI Verified"}],"rows":[{"id":"total-flight-time","label":"Total flight time (40 hr)"},{"id":"dual-training","label":"Flight training with instructor (20 hr)"},{"id":"solo-time","label":"Solo flight time (10 hr)"},{"id":"dual-xc","label":"Dual cross-country (3 hr)"},{"id":"night-training","label":"Night flight training (3 hr)"},{"id":"instrument-training","label":"Instrument-reference training (3 hr)"},{"id":"practical-test-prep","label":"Practical-test prep with instructor (3 hr / preceding 2 calendar months)"},{"id":"solo-xc","label":"Solo cross-country (5 hr)"}]},{"type":"note","title":"Special Experience Items","text":"Night XC: one night cross-country over 100 NM total distance. Night landings: 10 takeoffs + 10 landings to a full stop, each involving a flight in the traffic pattern. Solo XC: one 150 NM total solo cross-country; full-stop landings at 3 points; one segment >50 NM straight-line. Towered airport: 3 takeoffs + 3 landings to a full stop at an airport with an operating control tower."},{"type":"tracker","title":"Experience Audit: Cross-Country Training (3 hr minimum)","entryLabel":"Cross-country training flight","columns":[{"id":"date","label":"Date"},{"id":"aircraft","label":"Aircraft"},{"id":"time","label":"Time"},{"id":"logbook-entry","label":"Logbook Page / Entry"},{"id":"cfi","label":"CFI"}]},{"type":"tracker","title":"Experience Audit: Night Training (3 hr minimum)","entryLabel":"Night training flight","columns":[{"id":"date","label":"Date"},{"id":"aircraft","label":"Aircraft"},{"id":"time","label":"Time"},{"id":"logbook-entry","label":"Logbook Page / Entry"},{"id":"cfi","label":"CFI"}]},{"type":"tracker","title":"Experience Audit: Instrument-Reference Training (3 hr minimum)","entryLabel":"Instrument-reference training flight","columns":[{"id":"date","label":"Date"},{"id":"aircraft","label":"Aircraft"},{"id":"time","label":"Time"},{"id":"logbook-entry","label":"Logbook Page / Entry"},{"id":"cfi","label":"CFI"}]},{"type":"checklist","title":"Dual-Training Audit Sign-Off","items":[{"id":"dual-traced","label":"Dual-training requirements traced to actual entries"},{"id":"instructor-reviewed-audit","label":"Instructor reviewed this page"}]},{"type":"grid","title":"Experience Audit: Solo / Recent Prep","columns":[{"id":"logged-or-date","label":"Logged / Flight Date / Airport-Date"},{"id":"verified","label":"CFI Verified"}],"rows":[{"id":"solo-flight-time","label":"Solo Flight Time (10 hr minimum)"},{"id":"solo-xc","label":"Solo Cross-Country (5 hr minimum)"},{"id":"long-solo-xc","label":"Long Solo Cross-Country (150 NM total; full-stop landings at 3 points; one segment >50 NM straight-line)"},{"id":"towered-fullstops","label":"Towered-Airport Full-Stops (3 takeoffs + 3 landings to a full stop)"},{"id":"practical-test-prep","label":"Practical-Test Preparation (3 hr with instructor within preceding 2 calendar months)"}]},{"type":"fields","title":"Open Experience Gaps","items":[{"id":"missing-item","label":"Missing / unclear item"},{"id":"resolve-plan","label":"Plan to resolve"}]},{"type":"dual_checklist","title":"Practical-Test Prerequisite Check (final eligibility gate)","items":[{"id":"knowledge-test-passed","label":"Knowledge Test -- required knowledge test passed and still valid for the practical test"},{"id":"aktr-available","label":"Knowledge Test Report -- report available for the application / practical-test process"},{"id":"training-experience-accomplished","label":"Training + Experience -- required training and aeronautical experience for the certificate/rating have been accomplished"},{"id":"medical-satisfied","label":"Medical Qualification -- applicable medical certificate/qualification requirement satisfied"},{"id":"eligibility-satisfied","label":"Age / General Eligibility -- applicable age and private-pilot eligibility requirements satisfied"},{"id":"recent-prep-documented","label":"Recent Practical-Test Prep -- required instructor training within the preceding 2 calendar months is documented"},{"id":"deficiencies-reviewed-gate","label":"Knowledge Deficiencies -- deficient knowledge-test areas have been reviewed satisfactorily"},{"id":"application-complete-gate","label":"Application -- application is complete and ready for instructor certification/signature"},{"id":"endorsement-verified-gate","label":"Practical-Test Endorsement -- recommending instructor verified the certificate/rating-specific training/proficiency endorsement"}],"singleState":true},{"type":"fields","title":"Instructor Review","items":[{"id":"reviewed-with","label":"Reviewed with"},{"id":"review-date","label":"Date"}]},{"type":"checklist","title":"Ready To Proceed","items":[{"id":"ready-to-proceed","label":"Ready to proceed"}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('part1-closeout', '{"title":"Part I Closeout: Applicant Final Audit","pages":"22","intro":"Before moving to the aircraft, close every unresolved applicant-side item or transfer it to the master Open Items Log.","sourceCheck":null,"computed":false,"blocks":[{"type":"dual_checklist","title":"Part I Closeout","items":[{"id":"applicant-documents","label":"Applicant documents (Page 10)"},{"id":"identity-consistency","label":"Identity consistency (Page 11)"},{"id":"iacra-application","label":"IACRA / application (Page 12)"},{"id":"knowledge-test-report","label":"Knowledge Test Report (Page 13)"},{"id":"knowledge-deficiencies","label":"Knowledge deficiencies (Page 14)"},{"id":"endorsements","label":"Endorsements (Pages 15-17)"},{"id":"aeronautical-experience","label":"Aeronautical experience (Pages 18-20)"},{"id":"practical-test-prerequisites","label":"Practical-test prerequisites (Page 21)"}],"subLabels":["Verified","Open"],"singleState":true},{"type":"fields","title":"Unresolved Items To Transfer","items":[{"id":"unresolved-items","label":"Unresolved items to transfer","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('aircraft-documents', '{"title":"Aircraft Documents","pages":"24-27","intro":"Know what is on board. Know what is current. Know how to prove it. Build a one-page aircraft identity card from the actual POH/AFM, equipment records, and aircraft-specific data you will use on checkride day.","sourceCheck":"14 CFR § 91.203, § 91.9; FAA private-pilot practical-test guidance.","computed":false,"blocks":[{"type":"fields","title":"Aircraft Identity","items":[{"id":"make-model","label":"Make / Model"},{"id":"n-number","label":"N-Number"},{"id":"year","label":"Year"},{"id":"serial-number","label":"Serial Number"},{"id":"engine","label":"Engine"},{"id":"propeller","label":"Propeller"}]},{"type":"grid","title":"Weights / Capacities / Systems / Operating Limits","columns":[{"id":"value","label":"Value / Source"}],"rows":[{"id":"max-takeoff-weight","label":"Max takeoff weight"},{"id":"max-landing-weight","label":"Max landing weight"},{"id":"basic-empty-weight","label":"Basic empty weight"},{"id":"useful-load","label":"Useful load"},{"id":"usable-fuel","label":"Usable fuel"},{"id":"total-fuel","label":"Total fuel"},{"id":"oil-capacity","label":"Oil capacity"},{"id":"baggage-limits","label":"Baggage limits"},{"id":"electrical-system","label":"Electrical system"},{"id":"fuel-system","label":"Fuel system"},{"id":"flaps-gear","label":"Flaps / gear"},{"id":"pitot-static-avionics","label":"Pitot-static / avionics"},{"id":"v-speeds-source","label":"V-speeds source"},{"id":"cg-envelope-source","label":"CG envelope source"},{"id":"poh-limitations-section","label":"POH limitations section"},{"id":"placards-limitations","label":"Placards / limitations"}]},{"type":"fields","title":"Three Aircraft-Specific Questions I Expect To Be Asked","items":[{"id":"q1","label":"Question 1"},{"id":"q2","label":"Question 2"},{"id":"q3","label":"Question 3"}]},{"type":"dual_checklist","title":"Aircraft Documents Audit -- Document Location Board","items":[{"id":"airworthiness-cert","label":"Airworthiness certificate -- on aircraft / displayed as required"},{"id":"registration-cert","label":"Registration certificate -- on aircraft"},{"id":"operating-limitations","label":"Operating limitations / approved AFM or POH, as applicable -- aircraft / digital / binder"},{"id":"equipment-list","label":"Equipment list / KOEL, as applicable -- POH / records / binder"},{"id":"current-wb-data","label":"Current weight & balance data -- aircraft records / POH / binder"},{"id":"maintenance-records","label":"Maintenance records / logbooks -- owner / operator / maintenance records"},{"id":"ad-status","label":"Applicable AD status / compliance evidence -- maintenance records / current AD source"},{"id":"placards-markings","label":"Required placards / markings -- aircraft"}],"subLabels":["Where I expect to find it","Verified"]},{"type":"checklist","title":"Practical-Test Prep","items":[{"id":"can-locate-airworthiness-reg","label":"I can physically locate the airworthiness and registration certificates"},{"id":"know-records-location","label":"I know where the aircraft maintenance records and applicable AD evidence are kept"}]},{"type":"fields","title":"POH / AFM / Limitations Locator","items":[{"id":"operating-limits-section","label":"Operating Limitations: POH/AFM section/page"},{"id":"operating-limits-key-items","label":"Operating Limitations: key items I expect to use"},{"id":"wb-source","label":"Weight & Balance: aircraft-specific source/location"},{"id":"wb-revision-date","label":"Weight & Balance: latest data / revision date"},{"id":"performance-section","label":"Performance: POH/AFM section/page"},{"id":"performance-charts","label":"Performance: charts I expect to use"},{"id":"systems-section","label":"Systems: POH/AFM section/page"},{"id":"systems-to-explain","label":"Systems: systems I need to explain"},{"id":"supplements-title","label":"Supplements / STCs: supplement title/location"},{"id":"supplements-equipment","label":"Supplements / STCs: equipment affected"}]},{"type":"choice","title":"30-Second Source Test","text":"Can you locate the limitations, W&B data, performance charts, and supplements you will actually use within about 30 seconds?","id":"thirty-second-source-test","options":["Yes","Not yet"]},{"type":"grid","title":"Inspection Status Dashboard","columns":[{"id":"status","label":"Status (N/A or Current)"},{"id":"notes","label":"Notes"}],"rows":[{"id":"annual","label":"Annual -- 12 calendar months (generally required under §91.409(a))"},{"id":"100-hour","label":"100-Hour -- 100 hours time in service (applies under §91.409(b) conditions)"},{"id":"elt","label":"ELT Inspection -- 12 calendar months (for ELT required by §91.207; battery rules also apply)"},{"id":"transponder","label":"Transponder -- 24 calendar months (when using an ATC transponder covered by §91.413)"},{"id":"altimeter-static","label":"Altimeter / Static -- 24 calendar months (for controlled-airspace IFR operations under §91.411)"},{"id":"vor-check","label":"VOR Check -- 30 days (for IFR operations using VOR under §91.171)"},{"id":"recurring-ads","label":"Recurring ADs -- per the AD (only if an applicable AD imposes a recurring action)"}]},{"type":"note","title":"Use The Actual Operation","text":"A VFR private-pilot checkride does not automatically make every IFR-specific inspection applicable. Determine the operation, equipment, and regulatory trigger before deciding what is required."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('maintenance-airworthiness', '{"title":"Maintenance & Airworthiness","pages":"28-36","intro":"Not every inspection applies to every operation. Determine applicability first, then verify the date, interval, and supporting record.","sourceCheck":"14 CFR §§ 91.171, 91.207, 91.213, 91.409, 91.411, 91.413; Part 39; Part 43; §91.405.","computed":false,"blocks":[{"type":"fields","title":"Annual + 100-Hour Review","items":[{"id":"annual-last-date","label":"Annual: Last inspection date"},{"id":"annual-time-at-inspection","label":"Annual: Aircraft time at inspection"},{"id":"annual-record-location","label":"Annual: Record / logbook location"},{"id":"annual-next-due","label":"Annual: Next due / status"},{"id":"100hr-last-date","label":"100-Hour: Last inspection date"},{"id":"100hr-time-at-inspection","label":"100-Hour: Aircraft time at inspection"},{"id":"100hr-record-location","label":"100-Hour: Record / logbook location"},{"id":"100hr-next-due","label":"100-Hour: Next due / status"}]},{"type":"checklist","title":"Entry Located and Return-to-Service Status Verified","items":[{"id":"annual-verified","label":"Annual: entry located and return-to-service status verified"},{"id":"100hr-verified","label":"100-Hour: entry located and return-to-service status verified"}]},{"type":"checklist","title":"Does The 100-Hour Requirement Apply To This Aircraft / Operation?","items":[{"id":"carries-for-hire","label":"Will the aircraft carry a person (other than a crewmember) for hire?"},{"id":"instruction-for-hire","label":"Will flight instruction for hire be given in an aircraft provided by the person giving the instruction?"},{"id":"annual-in-place-of-100hr","label":"Is an annual inspection being used in place of a 100-hour inspection?"},{"id":"100hr-exceeded-enroute","label":"If the 100-hour is exceeded en route for inspection, has the excess been included in the next interval?"}]},{"type":"fields","title":"My Determination / Instructor-Mechanic Review","items":[{"id":"determination","label":"My determination / instructor-mechanic review","multiline":true}]},{"type":"fields","title":"Systems Inspection Applicability","items":[{"id":"elt-last-inspection","label":"ELT (§91.207): Last inspection"},{"id":"elt-battery-status","label":"ELT: Battery status"},{"id":"transponder-last-test","label":"Transponder (§91.413): Last test"},{"id":"transponder-due-status","label":"Transponder: Due/status"},{"id":"altimeter-last-test","label":"Altimeter/Static (§91.411): Last test"},{"id":"altimeter-ifr-applicable","label":"Altimeter/Static: IFR applicable?"},{"id":"vor-last-check","label":"VOR (§91.171): Last check"},{"id":"vor-used-for-ifr","label":"VOR: Used for IFR?"}]},{"type":"checklist","title":"Systems Inspection Verified","items":[{"id":"elt-verified","label":"ELT verified"},{"id":"transponder-verified","label":"Transponder verified"},{"id":"altimeter-verified","label":"Altimeter/Static verified"},{"id":"vor-verified","label":"VOR verified"}]},{"type":"choice","title":"My Operation","id":"my-operation","options":["VFR practical-test flight","IFR operation planned","Other / special circumstance"]},{"type":"fields","title":"Instructor / Mechanic Review Notes","items":[{"id":"review-notes","label":"Instructor / mechanic review notes","multiline":true}]},{"type":"note","title":"AD Compliance Worksheet -- Trace The Evidence","text":"1. Identify the Aircraft/Products -- airframe, engine, propeller, and installed appliances/equipment that may have applicable ADs. 2. Check a Current AD Source -- use current FAA AD information and the aircraft''s maintenance records; do not rely on an old printed list alone. 3. Match Applicability -- confirm whether each AD actually applies to the aircraft/product configuration. 4. Verify Compliance -- locate the maintenance-record evidence showing method/date of compliance. 5. Track Recurring Actions -- if the AD repeats, identify the interval and next due point."},{"type":"fields","title":"How This Aircraft Was Checked","items":[{"id":"ad-source-used","label":"Source / system used"},{"id":"ad-reviewed-with","label":"Reviewed with"},{"id":"ad-review-date","label":"Date"}]},{"type":"checklist","title":"AD Status Verified","items":[{"id":"ad-status-verified","label":"Status verified"}]},{"type":"tracker","title":"Recurring AD Tracker (leave blank if no recurring AD applies)","entryLabel":"Recurring AD","columns":[{"id":"ad-subject","label":"AD / Subject"},{"id":"applies-to","label":"Applies To"},{"id":"interval","label":"Interval"},{"id":"last-compliance","label":"Last Compliance"},{"id":"next-due","label":"Next Due"},{"id":"evidence","label":"Evidence"}]},{"type":"choice","title":"Recurring AD Status Check","id":"recurring-ad-status","options":["All applicable recurring ADs are current","No recurring ADs apply","Needs review"]},{"type":"fields","title":"Maintenance Record Locator","items":[{"id":"airframe-location","label":"Airframe: Location / page/search"},{"id":"engine-location","label":"Engine: Location / page/search"},{"id":"propeller-location","label":"Propeller: Location / page/search"},{"id":"avionics-location","label":"Avionics / Appliances: Location / page/search"},{"id":"inspections-location","label":"Inspections: Location / page/search"},{"id":"ads-location","label":"Airworthiness Directives: Location / page/search"},{"id":"alterations-location","label":"Alterations / STCs: Location / page/search"},{"id":"discrepancies-location","label":"Discrepancies / Deferred Items: Location / page/search"}]},{"type":"choice","title":"Show-Me Standard","text":"Pick one inspection, one AD, and one aircraft-specific data item. Can you locate the supporting record quickly and explain what the entry proves?","id":"maintenance-showme","options":["Yes","Not yet"]},{"type":"note","title":"Inoperative Equipment Decision Flow","text":"1. Approved MEL? If an approved MEL applies, use it together with the authorization and all conditions/limitations. 2. No MEL path available? For eligible aircraft/operations, continue through the §91.213(d) checks. 3. Required by type certification / equipment list / KOEL? If part of the aircraft''s VFR-day type certification or otherwise required by the equipment list/KOEL, stop and resolve. 4. Required by §91.205 or another operating rule? If yes for this operation, it must be operative unless another authorization applies. 5. Required by an AD? If an applicable AD requires it operative, stop and resolve. 6. Removed or deactivated + placarded correctly? Follow §91.213(d) removal/deactivation, placarding, and maintenance-record requirements as applicable. 7. No hazard determination -- an appropriately rated pilot or maintenance person determines the inoperative item does not create a hazard. Stop if you cannot support the determination: do not use this as a substitute for the regulation, an MEL, aircraft-specific equipment requirements, or qualified maintenance guidance."},{"type":"tracker","title":"Inoperative Equipment Practice Drills","entryLabel":"Decision drill","columns":[{"id":"scenario","label":"Scenario"},{"id":"sources","label":"Sources I would check"},{"id":"required-because","label":"Required / not required because"},{"id":"decision","label":"Action / final decision"},{"id":"cfi-reviewed","label":"CFI reviewed","type":"checkbox"}],"seedRows":[{"scenario":"Drill 1: A landing light is inoperative before a daytime VFR local flight."},{"scenario":"Drill 2: The transponder fails before a flight that would enter airspace where it is required."},{"scenario":"Drill 3: An installed gauge is inoperative, but you are unsure whether it appears on the equipment list / KOEL or is required by an AD."}]},{"type":"tracker","title":"Aircraft Discrepancy Action Log","entryLabel":"Discrepancy","columns":[{"id":"item-squawk","label":"Item / Squawk"},{"id":"date-found","label":"Date Found"},{"id":"disposition","label":"Disposition / Action"},{"id":"source-record","label":"Source / Record"},{"id":"closed","label":"Closed","type":"checkbox"}]},{"type":"choice","title":"Discrepancy Log Final Status","id":"discrepancy-final-status","options":["No unresolved discrepancies affecting the practical-test flight","Needs instructor / mechanic review"]},{"type":"fields","title":"Discrepancy Log Reviewer","items":[{"id":"reviewer","label":"Reviewer"},{"id":"review-date","label":"Date"}]},{"type":"dual_checklist","title":"DPE ''Show Me'' -- Airworthiness Drill","items":[{"id":"sm-airworthiness-cert","label":"Airworthiness certificate"},{"id":"sm-registration-cert","label":"Registration certificate"},{"id":"sm-annual-entry","label":"Annual inspection entry"},{"id":"sm-100hr-entry","label":"100-hour entry, if applicable"},{"id":"sm-elt","label":"ELT inspection / battery status"},{"id":"sm-transponder","label":"Transponder test, if applicable"},{"id":"sm-altimeter","label":"Altimeter/static test, if applicable"},{"id":"sm-vor","label":"VOR check, if applicable"},{"id":"sm-ad","label":"Applicable AD compliance evidence"},{"id":"sm-wb","label":"Weight & balance / equipment data"},{"id":"sm-poh-limits","label":"POH/AFM limitations"},{"id":"sm-discrepancy","label":"Open discrepancy disposition"}],"subLabels":["Found <30 sec","Explained","Needs work"]},{"type":"fields","title":"My Slowest Item","items":[{"id":"slowest-item","label":"Item"},{"id":"practice-plan","label":"Practice plan"}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('know-your-aircraft', '{"title":"Know Your Aircraft","pages":"37-39","intro":"Fill this page from your actual aircraft documents. Every number should have a source you can point to. Use the actual POH/AFM and aircraft configuration to build a concise systems map you can explain during the oral.","sourceCheck":null,"computed":false,"blocks":[{"type":"grid","title":"Aircraft Limitations + Capacities","columns":[{"id":"value","label":"Value"},{"id":"source","label":"Source"}],"rows":[{"id":"max-takeoff-weight","label":"Max Takeoff Weight"},{"id":"max-landing-weight","label":"Max Landing Weight"},{"id":"useful-load","label":"Useful Load"},{"id":"usable-fuel","label":"Usable Fuel"},{"id":"oil-capacity","label":"Oil Capacity"},{"id":"baggage-limit","label":"Baggage Limit"},{"id":"normal-cg-limits","label":"Normal Category CG Limits (Range)"},{"id":"utility-cg-limits","label":"Utility Category Limits, If Applicable (Range)"},{"id":"flap-limitation","label":"Flap Limitation"},{"id":"other-limitation","label":"Other Limitation I Expect To Discuss"}]},{"type":"choice","title":"Source Check","text":"Can you open the exact POH/AFM page, equipment data, or aircraft-specific record that supports each important value?","id":"limitations-source-check","options":["Yes"]},{"type":"fields","title":"Aircraft Systems Snapshot","items":[{"id":"electrical","label":"Electrical -- battery / alternator or generator / bus / protection / failure indications"},{"id":"fuel","label":"Fuel -- tanks / usable fuel / selectors / pumps / vents / drains"},{"id":"engine-propeller","label":"Engine + Propeller -- engine type / induction / ignition / cooling / propeller type"},{"id":"flight-controls","label":"Flight Controls -- primary controls / trim / flap system / unusual features"},{"id":"landing-gear-brakes","label":"Landing Gear + Brakes -- fixed/retractable / steering / braking / limitations"},{"id":"pitot-static-instruments","label":"Pitot-Static + Instruments -- sources / drains / heat / alternate static / affected instruments"},{"id":"avionics-autopilot","label":"Avionics / Autopilot -- installed equipment / power source / limitations / required supplements"},{"id":"cabin-environmental","label":"Cabin / Environmental -- heat / ventilation / CO considerations / emergency equipment"},{"id":"system-to-review-most","label":"System I need to review most / reason"}]},{"type":"grid","title":"V-Speeds + Performance Source Map","columns":[{"id":"value","label":"Value"},{"id":"meaning-when-used","label":"What It Means / When Used"},{"id":"source","label":"Source"}],"rows":[{"id":"vso","label":"VSO"},{"id":"vs1","label":"VS1"},{"id":"vr","label":"VR"},{"id":"vx","label":"VX"},{"id":"vy","label":"VY"},{"id":"vfe","label":"VFE"},{"id":"va","label":"VA"},{"id":"vno","label":"VNO"},{"id":"vne","label":"VNE"},{"id":"best-glide","label":"Best Glide"},{"id":"other1","label":"Other"},{"id":"other2","label":"Other"}]},{"type":"fields","title":"Performance Source Map","items":[{"id":"takeoff-chart-section","label":"Takeoff chart / section"},{"id":"landing-chart-section","label":"Landing chart / section"},{"id":"climb-cruise-source","label":"Climb / cruise source"},{"id":"wb-source","label":"W&B source"}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('part2-closeout', '{"title":"Part II Closeout: Aircraft Final Audit","pages":"40","intro":"Before moving to flight-planning, verify that the aircraft side of the checkride is organized, current, and explainable.","sourceCheck":null,"computed":false,"blocks":[{"type":"dual_checklist","title":"Part II Closeout","items":[{"id":"aircraft-snapshot","label":"Aircraft snapshot (Page 24)"},{"id":"aircraft-documents","label":"Aircraft documents (Page 25)"},{"id":"poh-afm-limitations","label":"POH / AFM / limitations (Page 26)"},{"id":"inspection-status","label":"Inspection status (Pages 27-29)"},{"id":"airworthiness-directives","label":"Airworthiness directives (Pages 30-31)"},{"id":"maintenance-record-locator","label":"Maintenance record locator (Page 32)"},{"id":"inoperative-equipment","label":"Inoperative equipment (Pages 33-34)"},{"id":"discrepancy-log","label":"Discrepancy log (Page 35)"},{"id":"dpe-showme-drill","label":"DPE show-me drill (Page 36)"},{"id":"limitations-systems-speeds","label":"Limitations / systems / speeds (Pages 37-39)"}],"subLabels":["Verified","Open"],"singleState":true},{"type":"fields","title":"Unresolved Aircraft Items To Transfer","items":[{"id":"unresolved-items","label":"Unresolved aircraft items to transfer","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('cross-country-planning', '{"title":"Cross-Country Planning","pages":"42-44","intro":"Build the plan. Explain the plan. Defend the decision. Be ready to explain how you selected the route and altitude -- including terrain, airspace, weather, and direction of flight.","sourceCheck":"14 CFR §91.103, §91.159; FAA-S-ACS-6C, Area of Operation I, Task D -- Cross-Country Flight Planning.","computed":false,"blocks":[{"type":"fields","title":"My Checkride Cross-Country","items":[{"id":"from","label":"From"},{"id":"to","label":"To"},{"id":"date-time","label":"Date / Time"},{"id":"aircraft-n-number","label":"Aircraft / N-Number"},{"id":"cruise-altitude","label":"Planned Cruise Altitude"}]},{"type":"note","title":"Flight Packet Index","text":"01 Route + Altitude (pages 43-44), 02 Weather + NOTAMs (pages 45-47), 03 Fuel (page 48), 04 Weight & Balance (pages 49-51), 05 Performance (pages 52-55), 06 Personal Minimums + ADM (pages 56-57), 07 Diversion + Contingencies (page 58), 08 Go / No-Go Brief (page 59)."},{"type":"fields","title":"Route Snapshot","items":[{"id":"departure-airport","label":"Departure airport"},{"id":"destination-airport","label":"Destination airport"},{"id":"primary-route","label":"Primary route / checkpoints"},{"id":"total-distance","label":"Total distance"},{"id":"ete","label":"Estimated time en route"}]},{"type":"fields","title":"Cruise Altitude","items":[{"id":"planned-altitude","label":"Planned altitude"},{"id":"magnetic-course","label":"Magnetic course"},{"id":"terrain-obstacle","label":"Terrain / obstacle concern"},{"id":"airspace-consideration","label":"Airspace consideration"},{"id":"why-altitude","label":"Why this altitude makes sense"}]},{"type":"tracker","title":"Checkpoint / Leg Map","entryLabel":"Leg","columns":[{"id":"course","label":"Course"},{"id":"dist","label":"Dist"},{"id":"gs","label":"GS"},{"id":"ete","label":"ETE"},{"id":"fuel","label":"Fuel"},{"id":"notes","label":"Notes / Checkpoint"}]},{"type":"fields","title":"Airport / Airspace Audit -- Departure Airport","items":[{"id":"dep-identifier","label":"Identifier / name"},{"id":"dep-runway","label":"Runway planned"},{"id":"dep-runway-length","label":"Runway length"},{"id":"dep-elevation","label":"Field elevation"},{"id":"dep-ctaf","label":"CTAF / tower / ground"}]},{"type":"fields","title":"Airport / Airspace Audit -- Destination Airport","items":[{"id":"dest-identifier","label":"Identifier / name"},{"id":"dest-runway","label":"Runway planned"},{"id":"dest-runway-length","label":"Runway length"},{"id":"dest-elevation","label":"Field elevation"},{"id":"dest-ctaf","label":"CTAF / tower / ground"}]},{"type":"checklist","title":"Airspace Review","items":[{"id":"class-bcde-identified","label":"Class B/C/D or E transition areas identified"},{"id":"special-use-reviewed","label":"Special-use airspace reviewed"},{"id":"tfr-reviewed","label":"TFR / security-sensitive areas reviewed"},{"id":"equipment-comm-considered","label":"Required equipment / communication considered"}]},{"type":"checklist","title":"Alternatives","items":[{"id":"diversion-selected","label":"At least one realistic diversion airport selected"},{"id":"runway-fuel-reviewed","label":"Runway / fuel availability reviewed"},{"id":"terrain-airspace-alternates-reviewed","label":"Terrain and airspace around alternates reviewed"},{"id":"can-explain-divert","label":"I can explain when I would divert"}]},{"type":"fields","title":"The Question I Expect The DPE To Ask","items":[{"id":"expected-question","label":"\"Why did you choose this route and this altitude?\""}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('weather-decision-making', '{"title":"Weather Decision Making","pages":"45-47","intro":"Record the weather picture, not just isolated products. Your goal is to explain what the atmosphere is doing along the route, then separate what is legal from what is smart.","sourceCheck":"FAA-S-ACS-6C Weather Information; FAA-H-8083-28B (2026 Aviation Weather Handbook); 14 CFR §91.103.","computed":false,"blocks":[{"type":"fields","title":"Weather Snapshot -- Departure","items":[{"id":"dep-metar","label":"METAR / current conditions"},{"id":"dep-taf","label":"TAF / trend"},{"id":"dep-wind-runway","label":"Wind / runway implication"}]},{"type":"fields","title":"Weather Snapshot -- Destination","items":[{"id":"dest-metar","label":"METAR / current conditions"},{"id":"dest-taf","label":"TAF / trend"},{"id":"dest-wind-runway","label":"Wind / runway implication"}]},{"type":"fields","title":"Weather Snapshot -- En Route","items":[{"id":"enroute-ceilings","label":"Ceilings / visibility trend"},{"id":"enroute-winds-aloft","label":"Winds aloft"},{"id":"enroute-cloud-terrain","label":"Cloud / terrain interaction"}]},{"type":"fields","title":"Weather Snapshot -- Hazards","items":[{"id":"hazards-airmet-sigmet","label":"AIRMET / SIGMET / Convective SIGMET"},{"id":"hazards-pireps","label":"PIREPs"},{"id":"hazards-thunderstorms","label":"Thunderstorms / icing / turbulence / LLWS"}]},{"type":"fields","title":"Weather Story -- In One Paragraph","items":[{"id":"weather-story","label":"What is the overall weather picture, what is changing, and what is the most important risk to this flight?","multiline":true}]},{"type":"grid","title":"Weather Decision Matrix","columns":[{"id":"my-limit","label":"My Limit"},{"id":"actual-forecast","label":"Actual / Forecast"},{"id":"action","label":"Action"}],"rows":[{"id":"ceiling","label":"Ceiling"},{"id":"visibility","label":"Visibility"},{"id":"surface-wind","label":"Surface wind"},{"id":"crosswind","label":"Crosswind"},{"id":"convective-weather","label":"Convective weather"},{"id":"turbulence","label":"Turbulence"},{"id":"icing-risk","label":"Icing risk / freezing level"}]},{"type":"fields","title":"Triggers That Change The Plan","items":[{"id":"triggers","label":"Write the specific conditions that would make you delay, cancel, turn around, or divert","multiline":true}]},{"type":"choice","title":"Today''s Weather Decision","id":"weather-decision","options":["Go as planned","Go with changes","Delay","No-go"]},{"type":"tracker","title":"Relevant NOTAMs","entryLabel":"NOTAM","columns":[{"id":"location","label":"Location"},{"id":"item-id","label":"Item / ID"},{"id":"what-changes","label":"What It Changes"},{"id":"action","label":"Action"}]},{"type":"checklist","title":"TFR / Security Review","items":[{"id":"tfrs-reviewed","label":"Current TFRs reviewed"},{"id":"no-prohibited-conflict","label":"Route does not create a prohibited / restricted conflict"}]},{"type":"checklist","title":"Services + Runways","items":[{"id":"runway-closures-reviewed","label":"Runway closures / lighting issues reviewed"},{"id":"fuel-services-considered","label":"Fuel / services limitations considered"}]},{"type":"fields","title":"The One NOTAM I Would Brief First","items":[{"id":"top-notam","label":"The one NOTAM I would brief first","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('wb-performance', '{"title":"W&B / Performance","pages":"48-55","intro":"Calculate the fuel required for the flight you intend to make, build the weight and balance calculation from aircraft-specific data, then use the conditions that actually exist to determine takeoff, landing, and climb performance.","sourceCheck":"14 CFR §91.151, §91.103(b); FAA-S-ACS-6C weight & balance / performance planning.","computed":false,"blocks":[{"type":"fields","title":"Fuel Plan -- Flight Inputs","items":[{"id":"fuel-on-board","label":"Planned fuel on board"},{"id":"cruise-fuel-flow","label":"Expected cruise fuel flow"},{"id":"taxi-runup","label":"Taxi / run-up allowance"},{"id":"ete-to-destination","label":"ETE to destination"},{"id":"diversion-allowance","label":"Planned alternate / diversion allowance"}]},{"type":"fields","title":"Fuel Plan -- Reserve","items":[{"id":"day-night","label":"Day or night operation"},{"id":"legal-reserve","label":"Legal VFR reserve"},{"id":"personal-reserve","label":"My personal reserve"},{"id":"total-fuel-required","label":"Total planned fuel required"},{"id":"fuel-at-destination","label":"Fuel remaining at destination"}]},{"type":"fields","title":"Fuel Math","items":[{"id":"taxi-runup-amt","label":"Taxi / run-up"},{"id":"climb-amt","label":"Climb"},{"id":"cruise-amt","label":"Cruise"},{"id":"contingency-amt","label":"Contingency / diversion"},{"id":"reserve-amt","label":"Reserve"},{"id":"total-required-amt","label":"Total required"}]},{"type":"choice","title":"Reserve Check","text":"Would you still be comfortable launching if the flight took longer than planned or the destination became unavailable?","id":"reserve-check","options":["Yes","No -- revise the plan"]},{"type":"tracker","title":"W&B Source Inputs -- Loading Inputs","entryLabel":"Loading item","columns":[{"id":"weight","label":"Weight"},{"id":"arm","label":"Arm"},{"id":"moment","label":"Moment"},{"id":"source","label":"Source"}],"seedRows":[{"item":"Basic empty weight"},{"item":"Pilot / front seat"},{"item":"Passenger / front seat"},{"item":"Rear passengers"},{"item":"Baggage area 1"},{"item":"Baggage area 2"},{"item":"Fuel at departure"},{"item":"Other installed / carried item"}]},{"type":"fields","title":"W&B Source Check","items":[{"id":"wb-source-check","label":"Where did the aircraft empty weight / moment come from? Where did passenger, baggage, and fuel assumptions come from?","multiline":true}]},{"type":"tracker","title":"W&B Calculation Workspace","entryLabel":"Calculation item","columns":[{"id":"weight","label":"Weight"},{"id":"arm","label":"Arm"},{"id":"moment","label":"Moment"},{"id":"check","label":"Check"}]},{"type":"fields","title":"Takeoff CG / Landing Check","items":[{"id":"total-weight","label":"Total weight"},{"id":"total-moment","label":"Total moment"},{"id":"cg-index","label":"Takeoff CG / Index"},{"id":"limit-envelope","label":"Limit / envelope"},{"id":"est-landing-weight","label":"Est. landing weight"},{"id":"est-landing-cg","label":"Est. CG / status"}]},{"type":"checklist","title":"Forward CG -- Talk Through","items":[{"id":"fwd-stability","label":"More longitudinal stability"},{"id":"fwd-elevator-force","label":"Greater elevator force / authority may be needed"},{"id":"fwd-performance","label":"Performance / stall implications considered"},{"id":"fwd-handling","label":"Takeoff / landing handling effects considered"}]},{"type":"checklist","title":"Aft CG -- Talk Through","items":[{"id":"aft-stability","label":"Less longitudinal stability"},{"id":"aft-stall-margin","label":"Reduced stall recovery margin / pitch sensitivity"},{"id":"aft-control","label":"Control / recovery implications considered"},{"id":"aft-never-exceed","label":"Never operate outside approved limits"}]},{"type":"fields","title":"Fuel Burn -- What Changes?","items":[{"id":"cg-shift-direction","label":"As fuel burns, where does the CG move in your aircraft? Direction of CG shift"},{"id":"landing-cg-status","label":"Does the airplane remain within limits at the planned landing weight? Landing CG status"},{"id":"cg-explanation","label":"My explanation in one sentence"}]},{"type":"fields","title":"Performance Inputs -- Airport / Runway","items":[{"id":"airport-runway","label":"Airport / runway"},{"id":"field-elevation","label":"Field elevation"},{"id":"runway-length-available","label":"Runway length available"},{"id":"surface-condition","label":"Surface / condition"},{"id":"slope-obstacle","label":"Slope / obstacle concern"}]},{"type":"fields","title":"Performance Inputs -- Atmosphere / Aircraft","items":[{"id":"oat","label":"OAT"},{"id":"altimeter-setting","label":"Altimeter setting"},{"id":"pressure-altitude","label":"Pressure altitude"},{"id":"density-altitude","label":"Density altitude"},{"id":"takeoff-weight","label":"Takeoff weight"}]},{"type":"fields","title":"Wind Components","items":[{"id":"wind","label":"Wind"},{"id":"runway-heading","label":"Runway heading"},{"id":"gusts","label":"Gusts"},{"id":"headwind-tailwind-component","label":"Headwind / tailwind component"},{"id":"crosswind-component","label":"Crosswind component"},{"id":"source-poh-section","label":"Source I will use: POH/AFM section, table, or graph"}]},{"type":"fields","title":"Takeoff Margin -- POH Result","items":[{"id":"to-ground-roll","label":"Ground roll"},{"id":"to-distance-obstacle","label":"Distance over obstacle"},{"id":"to-chart-assumptions","label":"Chart assumptions / corrections"},{"id":"to-runway-available","label":"Runway available"},{"id":"to-margin-remaining","label":"Published margin remaining"}]},{"type":"fields","title":"Takeoff Margin -- Real-World Check","items":[{"id":"to-surface-correction","label":"Surface / slope correction"},{"id":"to-wind-gust","label":"Wind / gust consideration"},{"id":"to-weight-da-effect","label":"Weight / density altitude effect"},{"id":"to-obstacle-abort","label":"Obstacle / abort consideration"},{"id":"to-safety-margin","label":"My added safety margin"}]},{"type":"fields","title":"Takeoff Margin Calculation","items":[{"id":"runway-available-amt","label":"Runway available"},{"id":"takeoff-distance-used","label":"Takeoff distance used"},{"id":"margin-amt","label":"Margin"},{"id":"abort-point","label":"What point on the runway would make you abort if acceleration or performance is not developing as expected?"}]},{"type":"choice","title":"Takeoff Decision","id":"takeoff-decision","options":["Acceptable","Replan","No-go"]},{"type":"fields","title":"Takeoff Decision Why","items":[{"id":"takeoff-decision-why","label":"Why"}]},{"type":"fields","title":"Landing Margin -- POH Result","items":[{"id":"ldg-ground-roll","label":"Ground roll"},{"id":"ldg-distance-obstacle","label":"Distance over obstacle"},{"id":"ldg-expected-weight","label":"Expected landing weight"},{"id":"ldg-runway-available","label":"Runway available"},{"id":"ldg-margin-remaining","label":"Published margin remaining"}]},{"type":"fields","title":"Landing Margin -- Arrival Conditions","items":[{"id":"ldg-wind-gusts","label":"Forecast wind / gusts"},{"id":"ldg-runway-condition","label":"Runway condition"},{"id":"ldg-density-altitude","label":"Density altitude"},{"id":"ldg-approach-obstacle","label":"Approach / obstacle concern"},{"id":"ldg-alternate","label":"Alternate runway / airport"}]},{"type":"fields","title":"Go-Around / Diversion Triggers","items":[{"id":"go-around-triggers","label":"Write the conditions that would make you go around, choose another runway, or divert before landing","multiline":true}]},{"type":"choice","title":"Landing Decision","id":"landing-decision","options":["Acceptable","Replan","Divert"]},{"type":"fields","title":"Landing Decision Why","items":[{"id":"landing-decision-why","label":"Why"}]},{"type":"fields","title":"Climb Performance -- Density Altitude","items":[{"id":"field-elevation-climb","label":"Field elevation"},{"id":"pressure-altitude-climb","label":"Pressure altitude"},{"id":"oat-climb","label":"OAT"},{"id":"calculated-da","label":"Calculated / reported DA"},{"id":"da-vs-standard","label":"Compared with standard conditions"}]},{"type":"fields","title":"Climb Performance -- Climb Plan","items":[{"id":"expected-rate-of-climb","label":"Expected rate of climb"},{"id":"climb-speed-config","label":"Climb speed / configuration"},{"id":"terrain-obstacle-need","label":"Terrain / obstacle need"},{"id":"time-distance-to-altitude","label":"Time / distance to altitude"},{"id":"escape-turn-back","label":"Escape / turn-back option"}]},{"type":"checklist","title":"What Degrades Climb Performance?","items":[{"id":"higher-da","label":"Higher density altitude"},{"id":"higher-weight","label":"Higher weight"},{"id":"tailwind-terrain","label":"Tailwind / terrain geometry"},{"id":"improper-config","label":"Improper configuration / speed"},{"id":"engine-prop-degradation","label":"Engine / propeller limitations or degradation"}]},{"type":"fields","title":"My Climb Performance Decision","items":[{"id":"min-performance-wanted","label":"Minimum performance I want to see"},{"id":"if-not-seen","label":"If I do not see it, I will"}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('personal-minimums-adm', '{"title":"Personal Minimums / ADM","pages":"56-59","intro":"Set your limits before the trip becomes emotionally important. Legal minimums are not the same thing as personal operating limits. Run the risks before you run the engine.","sourceCheck":"FAA-S-ACS-6C risk management; FAA-H-8083-2A Risk Management Handbook; 14 CFR §91.103.","computed":false,"blocks":[{"type":"grid","title":"My Personal Minimums (Day / Night)","columns":[{"id":"day","label":"Day"},{"id":"night","label":"Night"},{"id":"notes","label":"Notes / Conditions"}],"rows":[{"id":"ceiling","label":"Ceiling"},{"id":"visibility","label":"Visibility"},{"id":"surface-wind","label":"Surface wind"},{"id":"crosswind","label":"Crosswind"},{"id":"gust-spread","label":"Gust spread"},{"id":"convective-proximity","label":"Convective proximity"},{"id":"recent-experience","label":"Recent experience / proficiency"},{"id":"fuel-reserve-beyond-legal","label":"Fuel reserve beyond legal minimum"}]},{"type":"fields","title":"Automatic No-Go Conditions","items":[{"id":"no-go-conditions","label":"List the conditions that end the discussion immediately -- regardless of schedule, passengers, cost, or convenience","multiline":true}]},{"type":"fields","title":"PAVE -- Pilot / Aircraft","items":[{"id":"pilot-imsafe-notes","label":"Pilot -- IMSAFE, proficiency, experience, currency"},{"id":"pilot-top-risk","label":"Pilot -- Top risk / control"},{"id":"aircraft-notes","label":"Aircraft -- Airworthiness, performance, equipment, fuel"},{"id":"aircraft-top-risk","label":"Aircraft -- Top risk / control"}]},{"type":"fields","title":"PAVE -- enVironment / External Pressures","items":[{"id":"environment-notes","label":"enVironment -- Weather, terrain, runway, airspace, night"},{"id":"environment-top-risk","label":"enVironment -- Top risk / control"},{"id":"external-notes","label":"External Pressures -- Schedule, passengers, cost, ego, get-there-itis"},{"id":"external-top-risk","label":"External Pressures -- Top risk / control"}]},{"type":"checklist","title":"IMSAFE -- My Status Today","items":[{"id":"illness","label":"Illness"},{"id":"medication","label":"Medication"},{"id":"stress","label":"Stress"},{"id":"alcohol","label":"Alcohol"},{"id":"fatigue","label":"Fatigue"},{"id":"eating-emotion","label":"Eating / Emotion"}]},{"type":"choice","title":"Overall Risk","id":"overall-risk","options":["Low","Manageable with controls","Too high -- no-go"]},{"type":"fields","title":"Diversion + Backup Plan -- Primary Diversion","items":[{"id":"primary-airport","label":"Airport / identifier"},{"id":"primary-trigger","label":"Trigger to use it"},{"id":"primary-distance-heading","label":"Distance / heading estimate"},{"id":"primary-fuel-required","label":"Fuel required"},{"id":"primary-runway-services","label":"Runway / services"}]},{"type":"fields","title":"Diversion + Backup Plan -- Secondary Option","items":[{"id":"secondary-airport","label":"Airport / identifier"},{"id":"secondary-trigger","label":"Trigger to use it"},{"id":"secondary-distance-heading","label":"Distance / heading estimate"},{"id":"secondary-fuel-required","label":"Fuel required"},{"id":"secondary-runway-services","label":"Runway / services"}]},{"type":"checklist","title":"In-Flight Triggers","items":[{"id":"weather-below-minimums","label":"Weather below personal minimums"},{"id":"fuel-worse-than-plan","label":"Fuel burn / groundspeed worse than plan"},{"id":"destination-issue","label":"Destination runway / airport issue"},{"id":"passenger-condition-changes","label":"Passenger / pilot condition changes"},{"id":"aircraft-discrepancy","label":"Aircraft discrepancy develops"}]},{"type":"fields","title":"Turn-Around Decision","items":[{"id":"turn-around-condition","label":"The condition that makes me turn around early","multiline":true}]},{"type":"dual_checklist","title":"Go / No-Go Brief","items":[{"id":"route-ready","label":"Route -- route / altitude / airspace make sense"},{"id":"weather-ready","label":"Weather -- conditions and trends are within limits"},{"id":"fuel-ready","label":"Fuel -- fuel plan includes reserve and contingency"},{"id":"wb-ready","label":"W&B -- takeoff and landing loading remain within limits"},{"id":"performance-ready","label":"Performance -- takeoff, climb, and landing margins are acceptable"},{"id":"pilot-adm-ready","label":"Pilot / ADM -- personal condition and external pressures are controlled"}],"subLabels":["Ready"],"singleState":true},{"type":"choice","title":"My Decision","id":"go-no-go-decision","options":["Go","Go with changes","Delay","No-go"]},{"type":"fields","title":"My Decision Why","items":[{"id":"decision-why","label":"Why","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('part3-closeout', '{"title":"Part III Closeout: Flight Final Audit","pages":"60","intro":"Before moving to oral-exam practice, verify that the complete flight-planning story is organized, current, and explainable.","sourceCheck":null,"computed":false,"blocks":[{"type":"dual_checklist","title":"Part III Closeout","items":[{"id":"flight-packet-map","label":"Flight packet map (Page 42)"},{"id":"route-altitude","label":"Route + altitude (Pages 43-44)"},{"id":"weather-notams","label":"Weather + NOTAMs (Pages 45-47)"},{"id":"fuel-plan","label":"Fuel plan (Page 48)"},{"id":"weight-balance","label":"Weight & balance (Pages 49-51)"},{"id":"performance","label":"Performance (Pages 52-55)"},{"id":"personal-minimums-adm","label":"Personal minimums + ADM (Pages 56-57)"},{"id":"diversion-contingencies","label":"Diversion / contingencies (Page 58)"},{"id":"go-no-go-brief","label":"Go / no-go brief (Page 59)"}],"subLabels":["Verified","Open"],"singleState":true},{"type":"fields","title":"Unresolved Flight Items To Transfer","items":[{"id":"unresolved-items","label":"Unresolved flight items to transfer","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('dpe-show-me-drill', '{"title":"DPE \"Show Me\" Drill","pages":"61-65","intro":"The goal is not to memorize every page number. The goal is to locate the right source quickly, explain what it says, and apply it to your actual flight. Locate. Explain. Apply.","sourceCheck":"FAA-S-ACS-6C; Apex Advantage Module 20 -- mock oral practice; 14 CFR 61.39; AC 61-65K.","computed":false,"blocks":[{"type":"note","title":"The Three Steps","text":"1. Locate -- find the exact document, record, chart, regulation, or aircraft source. 2. Explain -- state what the source means in plain language, not just what it is called. 3. Apply -- connect the source to this aircraft, this route, this weather, or this decision."},{"type":"choice","title":"Self-Rating","id":"showme-self-rating","options":["Green -- I can locate and explain it without help.","Yellow -- I can get there, but I am slow or unsure.","Red -- I cannot locate it or cannot explain how it applies."]},{"type":"note","title":"The Rule","text":"If you cannot locate the source, do not bluff. Slow down, say what you know, find the source, verify it, then answer."},{"type":"dual_checklist","title":"Applicant \"Show Me\" -- Personal Documents + Eligibility Evidence","items":[{"id":"sm-id","label":"Show me the identification you will present."},{"id":"sm-certificate","label":"Show me your current pilot certificate."},{"id":"sm-medical","label":"Show me the applicable medical qualification / documentation."},{"id":"sm-aktr","label":"Show me your Airman Knowledge Test Report."},{"id":"sm-application","label":"Show me the practical-test application / IACRA record."},{"id":"sm-endorsement","label":"Show me the practical-test endorsement."},{"id":"sm-experience","label":"Show me where your aeronautical experience is documented."}],"subLabels":["Locate","Explain"]},{"type":"fields","title":"Applicant Follow-Up Practice","items":[{"id":"applicant-followup","label":"Pick any item above. Explain what makes it current, applicable, or complete -- then identify who you would ask or what source you would check if something did not match.","multiline":true}]},{"type":"dual_checklist","title":"Aircraft \"Show Me\" -- Documents, Records, Applicability","items":[{"id":"sm-registration","label":"Show me the aircraft registration."},{"id":"sm-airworthiness","label":"Show me the airworthiness certificate."},{"id":"sm-limitations","label":"Show me the operating limitations / POH or AFM."},{"id":"sm-wb","label":"Show me the current weight-and-balance / equipment information."},{"id":"sm-annual","label":"Show me evidence of the annual inspection."},{"id":"sm-other-inspection","label":"Show me other applicable inspection evidence for today''s operation."},{"id":"sm-ad-compliance","label":"Show me how AD compliance is tracked."},{"id":"sm-inop-decision","label":"Show me how you would determine whether an inoperative item can be deferred."}],"subLabels":["Locate","Explain"]},{"type":"fields","title":"Aircraft Examiner Follow-Up","items":[{"id":"aircraft-followup","label":"For one item, answer: What is required? Where is the proof? Does it apply today? What would make the aircraft a no-go?","multiline":true}]},{"type":"dual_checklist","title":"Flight \"Show Me\" -- Route, Weather, Fuel, Performance, Decision","items":[{"id":"sm-route","label":"Show me the planned route and checkpoints."},{"id":"sm-altitude","label":"Show me why you selected this altitude."},{"id":"sm-weather","label":"Show me the weather information driving your decision."},{"id":"sm-notam","label":"Show me the NOTAM / airport-status items that matter."},{"id":"sm-fuel","label":"Show me your fuel plan and reserve."},{"id":"sm-wb-calc","label":"Show me the W&B calculation for this loading."},{"id":"sm-performance","label":"Show me today''s takeoff / landing performance."},{"id":"sm-diversion","label":"Show me your primary diversion or backup plan."}],"subLabels":["Locate","Explain"]},{"type":"note","title":"Connect The Story","text":"Do not answer these as eight separate facts. Practice explaining how one input changes another: weather changes route; loading changes performance; performance changes margins; margins change the decision."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('oral-answer-framework', '{"title":"Oral Answer Framework","pages":"66-70","intro":"Use the same structure when the question is simple, technical, or scenario-based. The structure keeps your answer organized without turning it into a memorized script.","sourceCheck":"FAA-S-ACS-6C; Apex Advantage Modules 19-20.","computed":false,"blocks":[{"type":"note","title":"The Four-Step Answer","text":"1. Answer -- state the rule, concept, limitation, or conclusion clearly. 2. Source -- identify where you would verify it: regulation, ACS, POH/AFM, chart, record, or weather source. 3. Apply -- explain how it applies to this airplane, this route, these conditions, or this operation. 4. Decide -- state what you would actually do as PIC."},{"type":"fields","title":"Practice Question","items":[{"id":"practice-question","label":"Question"},{"id":"practice-answer","label":"My answer / source / application / decision","multiline":true}]},{"type":"note","title":"When You Don''t Know -- Handle Uncertainty Professionally","text":"Uncertainty is not a cue to guess. It is a cue to slow down, identify the right source, and show sound judgment. Pause. Verify. Apply. 1. Pause and make sure you understand the question. 2. State the part you are confident about -- without inventing the rest. 3. Name the source you would use to verify the uncertain part. 4. Locate the source and confirm the answer. 5. Apply it to the scenario and state your decision."},{"type":"note","title":"Practice A Clean Recovery","text":"\"I am not completely sure of the exact requirement. I would verify it in...\" / \"What I know is... The part I need to confirm is...\" / \"For this flight, after I verify that, my decision would be...\" Do not fill silence with guesses, absolutes, or invented numbers. A disciplined lookup is stronger than confident speculation."},{"type":"note","title":"DPE Follow-Ups -- The Follow-Up Ladder","text":"Many oral questions are only the first layer. Practice the question behind the question so your reasoning stays intact when the scenario changes. WHY? -- explain the reason behind the rule, limitation, or decision. WHAT IF? -- change one condition and decide whether the answer changes. SHOW ME -- locate the source that supports the answer. WHAT CHANGES? -- identify the variable that matters most. WHEN WOULD YOU SAY NO? -- state the threshold that would change the decision."},{"type":"fields","title":"Build Your Own Follow-Up Chain","items":[{"id":"followup-topic","label":"Topic"},{"id":"followup-initial-question","label":"Initial question"},{"id":"followup-scenario-change","label":"Follow-up that changes the scenario"},{"id":"followup-source","label":"Source I would show"}]},{"type":"tracker","title":"10-Question Rapid-Fire Oral Log","entryLabel":"Question","columns":[{"id":"topic-question","label":"Topic / Question"},{"id":"confidence","label":"Confidence","type":"select","options":["Confident","Needs Review"]},{"id":"source","label":"Source"},{"id":"action","label":"Action","type":"select","options":["Review"]}]},{"type":"fields","title":"The Question That Got Me","items":[{"id":"toughest-question","label":"Write the one question or follow-up that exposed the biggest gap today","multiline":true}]},{"type":"tracker","title":"Oral Weak-Area Action Plan","entryLabel":"Weak area","columns":[{"id":"topic-acs-area","label":"Topic / ACS Area"},{"id":"what-missed","label":"What I Missed"},{"id":"fix-action","label":"Fix / Study Action"},{"id":"source","label":"Source"},{"id":"recheck","label":"Recheck"}]},{"type":"choice","title":"Ready To Close","text":"I will not mark an item closed until I can answer it again, locate the supporting source, and handle at least one follow-up question.","id":"oral-weak-area-ready","options":["All high-priority oral gaps retested"]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('cfi-final-review', '{"title":"CFI Final Review","pages":"72-73","intro":"Use this as a preparation review with your instructor. This page is not an FAA endorsement and does not replace any required logbook or IACRA action. Anything still unresolved now needs an owner and a deadline.","sourceCheck":"AC 61-65K; FAA-S-ACS-6C; this page is a training aid, not an FAA endorsement.","computed":false,"blocks":[{"type":"dual_checklist","title":"Preparation Review -- One Last System Check","items":[{"id":"applicant-reviewed","label":"Applicant -- documents, application, knowledge test, endorsements, aeronautical experience"},{"id":"aircraft-reviewed","label":"Aircraft -- documents, inspections, airworthiness, records, limitations"},{"id":"flight-reviewed","label":"Flight -- route, weather, NOTAMs, fuel, W&B, performance, contingencies"},{"id":"oral-reviewed","label":"Oral -- Show Me drill, answer framework, weak-area retest"}],"subLabels":["Reviewed"],"singleState":true},{"type":"tracker","title":"Open Items Before Sign-Off","entryLabel":"Open item","columns":[{"id":"description","label":"Item"}]},{"type":"fields","title":"Reviewed With","items":[{"id":"reviewed-with","label":"Reviewed with"},{"id":"review-date","label":"Date"}]},{"type":"note","title":"Note","text":"Preparation review only -- use the required FAA endorsement language separately when applicable."},{"type":"tracker","title":"Final Open-Item Closure","entryLabel":"Item to close","columns":[{"id":"category","label":"Category","type":"select","options":["Locate","Correct","Verify","Review with CFI"]},{"id":"description","label":"Description"}]},{"type":"fields","title":"Final Transfer","items":[{"id":"highest-priority-item","label":"Highest-priority unresolved item"},{"id":"owner","label":"Owner"},{"id":"due","label":"Due"},{"id":"what-closes-it","label":"What closes it"},{"id":"proof-location","label":"Where the final proof will live"}]},{"type":"choice","title":"Final Closure Status","id":"final-closure-status","options":["No unresolved safety / eligibility / airworthiness item remains"]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('night-before-checklist', '{"title":"Night-Before Checklist","pages":"74-76","intro":"Use the final week to close gaps, not to rebuild the entire checkride plan. The night before is for organization and rest -- not a panic-study marathon.","sourceCheck":"Apex Advantage Module 21 -- practical-test logistics and readiness.","computed":false,"blocks":[{"type":"checklist","title":"7 Days Out -- Applicant","items":[{"id":"7d-application-reviewed","label":"Application / IACRA reviewed"},{"id":"7d-aktr-located","label":"Knowledge Test Report + ID located"},{"id":"7d-endorsements-rechecked","label":"Endorsements / experience rechecked"}]},{"type":"checklist","title":"7 Days Out -- Aircraft","items":[{"id":"7d-aircraft-availability","label":"Aircraft availability confirmed"},{"id":"7d-maintenance-rechecked","label":"Maintenance / inspection status rechecked"},{"id":"7d-discrepancies-resolved","label":"Known discrepancies resolved / understood"}]},{"type":"checklist","title":"7 Days Out -- Flight","items":[{"id":"7d-route-planning-complete","label":"Assigned route / planning complete"},{"id":"7d-weather-notam-rehearsed","label":"Weather / NOTAM process rehearsed"},{"id":"7d-wb-performance-ready","label":"W&B + performance source data ready"}]},{"type":"checklist","title":"7 Days Out -- You","items":[{"id":"7d-sleep-protected","label":"Sleep / schedule protected"},{"id":"7d-mock-oral-retested","label":"Mock oral weak areas retested"},{"id":"7d-instructor-questions-resolved","label":"Questions for instructor resolved"}]},{"type":"fields","title":"My Priority This Week","items":[{"id":"week-priority","label":"The one thing that would most improve my readiness if I fixed it today","multiline":true}]},{"type":"checklist","title":"48 Hours Out -- Logistics","items":[{"id":"48h-time-location","label":"Time / location confirmed"},{"id":"48h-dpe-contact","label":"DPE contact instructions reviewed"},{"id":"48h-payment-ready","label":"Payment method ready"},{"id":"48h-transportation","label":"Transportation / arrival plan set"}]},{"type":"checklist","title":"48 Hours Out -- Aircraft","items":[{"id":"48h-aircraft-scheduled","label":"Aircraft scheduled"},{"id":"48h-fuel-plan","label":"Fuel plan understood"},{"id":"48h-maintenance-rechecked","label":"Maintenance status rechecked"},{"id":"48h-materials-accessible","label":"Required materials accessible"}]},{"type":"checklist","title":"48 Hours Out -- Flight","items":[{"id":"48h-route-reviewed","label":"Route / airports reviewed"},{"id":"48h-weather-monitored","label":"Weather trend monitored"},{"id":"48h-notams-rechecked","label":"NOTAMs / TFRs rechecked"},{"id":"48h-performance-ready","label":"Performance inputs ready to refresh"}]},{"type":"checklist","title":"48 Hours Out -- Personal","items":[{"id":"48h-sleep-protected","label":"Sleep protected"},{"id":"48h-meals-hydration","label":"Meals / hydration planned"},{"id":"48h-no-cramming","label":"No unnecessary late-night cramming"},{"id":"48h-imsafe-addressed","label":"IMSAFE concerns addressed"}]},{"type":"note","title":"Note","text":"If new information changes the risk picture, change the plan. The checkride date is not a reason to force the flight."},{"type":"checklist","title":"Night-Before -- Charge","items":[{"id":"charge-efb","label":"EFB / tablet"},{"id":"charge-phone","label":"Phone"},{"id":"charge-battery","label":"Backup battery"},{"id":"charge-headset","label":"Headset batteries / power"}]},{"type":"checklist","title":"Night-Before -- Pack","items":[{"id":"pack-id","label":"ID / certificates"},{"id":"pack-logbook","label":"Logbook / AKTR"},{"id":"pack-binder","label":"Binder / flight-planning materials"},{"id":"pack-headset","label":"Headset / calculator / plotter as needed"}]},{"type":"checklist","title":"Night-Before -- Confirm","items":[{"id":"confirm-meeting","label":"Meeting time / location"},{"id":"confirm-aircraft","label":"Aircraft status"},{"id":"confirm-forecast","label":"Forecast / major weather trend"},{"id":"confirm-payment","label":"Payment method"}]},{"type":"checklist","title":"Night-Before -- Do","items":[{"id":"do-eat-hydrate","label":"Eat / hydrate"},{"id":"do-alarms","label":"Set alarms / travel buffer"},{"id":"do-review-notes","label":"Review only high-priority notes"},{"id":"do-stop-sleep","label":"Stop and sleep"}]},{"type":"fields","title":"Last Question Tonight","items":[{"id":"last-question","label":"Is there anything unresolved that could affect eligibility, airworthiness, or safety? If yes, identify the owner now -- do not hide it until morning.","multiline":true}]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('checkride-morning', '{"title":"Checkride Morning","pages":"77","intro":"Use this page before you meet the examiner. The goal is calm confirmation, not last-minute reconstruction.","sourceCheck":"FAA-S-ACS-6C risk management; Apex Advantage Module 21.","computed":false,"blocks":[{"type":"checklist","title":"Me -- Personally Prepared","items":[{"id":"materials-with-me","label":"Required applicant materials are with me."},{"id":"imsafe-assessed","label":"I have assessed fitness using IMSAFE."},{"id":"rested-fed-hydrated","label":"I am rested, fed, hydrated, and focused."},{"id":"endorsement-actions-complete","label":"My required endorsement / application actions are complete."}]},{"type":"checklist","title":"Aircraft -- Safe. Airworthy. Ready.","items":[{"id":"documents-available","label":"Aircraft documents are available."},{"id":"preflight-status-understood","label":"Preflight / discrepancy status is understood."},{"id":"fuel-sufficient","label":"Fuel is sufficient for the planned operation."},{"id":"wb-refreshed","label":"W&B / performance have been refreshed as needed."}]},{"type":"checklist","title":"Flight -- Planned. Informed. With Margins.","items":[{"id":"weather-supports-plan","label":"Weather supports the plan within my limits."},{"id":"notams-current","label":"NOTAMs / airport status are current."},{"id":"xc-materials-ready","label":"Cross-country materials are ready."},{"id":"diversion-realistic","label":"Diversion / backup options remain realistic."}]},{"type":"checklist","title":"Decision -- The Right Decision.","items":[{"id":"would-make-flight-today","label":"I would make this flight today even if it were not a checkride."}]},{"type":"note","title":"Note","text":"If the final answer changes from GO to NO-GO, that is good aeronautical decision-making -- not a failed checkride morning."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('master-quick-reference', '{"title":"Master Quick-Reference Checklist","pages":"78","intro":"One page. Five categories. Nothing here replaces the source material -- this page only confirms that the complete system is ready.","sourceCheck":"FAA-S-ACS-6C; AC 61-65K; aircraft documents/records; current flight-planning information.","computed":true,"blocks":[{"type":"note","title":"Verify The Whole Story","text":"Applicant: ID / pilot certificate, medical qualification as applicable, Knowledge Test Report, IACRA / application, required endorsements / experience. Aircraft: registration / airworthiness, operating limitations, W&B / equipment data, inspection / AD status, discrepancies / inop-item resolution. Flight: route / altitude / airports, weather / NOTAMs, fuel, weight & balance, performance / diversion. Oral: Show Me drills, answer framework, weak areas retested, sources easy to locate, follow-up reasoning practiced. Logistics: time / location, payment method, devices / materials, arrival buffer, rest / food / hydration."},{"type":"choice","title":"Final Check","id":"master-quick-ref-final","options":["Every high-priority open item is closed or has a clear resolution plan"]}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();

insert into public.checkride_binder_content (section_id, content) values ('notes-reference', '{"title":"Notes & Reference","pages":"79-80","intro":"Use authoritative sources when the exact answer matters. This workbook organizes the work; it does not replace the source.","sourceCheck":"FAA source list verified September 2026.","computed":false,"blocks":[{"type":"note","title":"Source Map","text":"Private Pilot ACS -- FAA-S-ACS-6C: task standards, knowledge, risk management, skills, references. Endorsement Guidance -- AC 61-65K: current FAA guidance and sample endorsement language. Federal Regulations -- 14 CFR Parts 61 & 91: certification, eligibility, operating, equipment, inspection, and preflight rules. Aircraft Source -- POH / AFM + supplements: limitations, systems, performance, procedures, weight and balance. Aircraft Records -- maintenance records: inspection status, AD compliance, repairs / alterations, aircraft-specific history. Current Flight Info -- FAA / approved briefing sources: weather, NOTAMs, airport status, TFRs, current operational information."},{"type":"fields","title":"My Aircraft / Local Source Notes","items":[{"id":"poh-revision","label":"POH / AFM revision or edition"},{"id":"maintenance-record-location","label":"Maintenance-record location / custodian"},{"id":"other-references","label":"Other instructor / school references"}]},{"type":"fields","title":"Final Notes + Version Control","items":[{"id":"final-notes","label":"Last notes","multiline":true}]},{"type":"checklist","title":"Final Self-Check","items":[{"id":"know-materials-location","label":"I know where my required materials are."},{"id":"know-where-to-verify","label":"I know where to verify an answer when I am uncertain."},{"id":"can-explain-connections","label":"I can explain how the aircraft, flight plan, weather, and risk picture fit together."},{"id":"same-safety-decision","label":"I will make the same safety decision I would make if this were not a checkride."}]},{"type":"note","title":"Disclaimer","text":"This workbook is a training and organization aid. It does not guarantee practical-test success or replace current FAA requirements, aircraft documents, or instructor guidance. Apex Advantage Private Pilot Checkride Binder Builder -- Version 1.0 production draft. FAA references reviewed September 2026."}]}'::jsonb)
  on conflict (section_id) do update set content = excluded.content, updated_at = now();
